const pptxgen = require("pptxgenjs");

// Midnight Executive palette
const NAVY = "1E2761";
const NAVY_DARK = "151C4A";
const ICE = "CADCFC";
const WHITE = "FFFFFF";
const INK = "1B1F3B";
const MUTED = "6B7394";
const GREEN = "2E8B57";
const AMBER = "C9862B";
const RED = "B0413E";
const CARD_BG = "F4F6FC";

const FONT_HEAD = "Cambria";
const FONT_BODY = "Calibri";

function circle(slide, x, y, d, fill, label, labelColor) {
  slide.addShape("ellipse", { x, y, w: d, h: d, fill: { color: fill }, line: { type: "none" } });
  slide.addText(label, {
    x, y, w: d, h: d, align: "center", valign: "middle",
    fontFace: FONT_BODY, bold: true, fontSize: d > 0.5 ? 16 : 12, color: labelColor || WHITE,
    isTextBox: true, margin: 0,
  });
}

function footer(slide, text, dark) {
  slide.addText(text, {
    x: 0.5, y: 7.08, w: 12.3, h: 0.3, fontFace: FONT_BODY, fontSize: 10,
    color: dark ? "8A93BE" : MUTED, align: "left", isTextBox: true, margin: 0,
  });
}

